WITH session_totals AS (SELECT session_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(page))) AS page_values, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range FROM web_events GROUP BY session_id) SELECT s.id, s.started_at, s.country, st.page_values, st.duration_sec_range FROM sessions s LEFT JOIN session_totals st ON s.id = st.session_id WHERE st.duration_sec_range >= 64;
